 "content": "def transform(grid):
    """For divided binary panels, mark locations where both sides are background."""
    # The separator is the full-height monochrome divider; panel widths may differ.
    separator = next(
        c for c in range(len(grid[0]))
        if all(row[c] == grid[0][c] for row in grid)
    )
    left = [row[:separator] for row in grid]
    right = [row[separator + 1:] for row in grid]
    width = min(len(left[0]), len(right[0]))
    return [
        [3 if left[r][c] == 0 and right[r][c] == 0 else 0 for c in range(width)]
        for r in range(len(grid))
    ]
",
